// Форма обвязки к настоящему браузеру.
//
// ОТДАЁТ ЗОНА-ВЛАДЕЛЕЦ, и это не формальность. Потребитель, объявивший форму у себя, объявляет
// её по тому, чем пользуется сам: разойдутся они молча — на правке обвязки чужой файл останется
// верным по типам и неверным по делу. Пробел нашёл владелец `skin-reference`, объявив форму
// узко и назвав это пробелом вслух.
//
// Протокол здесь НЕ типизируется: `call` принимает метод строкой и отдаёт разбор `unknown`.
// Расписать протокол значило бы завести вторую копию чужой спецификации, которая устареет на
// первом же обновлении браузера. Вызывающий знает, что спросил, и приводит ответ сам.

/** Путь к бинарю Chromium в кеше, или `null` — проверять рисование нечем. */
export function findChrome(): string | null;

/** Один вызов протокола в присоединённой вкладке. */
export type Call = (method: string, params?: Record<string, unknown>) => Promise<any>;

/**
 * Поднимает браузер, отдаёт говорилку протокола, гасит в любом исходе.
 *
 * @throws если бинаря нет — прямо, а не невнятным падением: пункт гейта тогда незакрыт, и
 *   подменять его поиском строки нельзя.
 */
export function withChrome<T>(run: (call: Call) => Promise<T>): Promise<T>;

/** Загружает разметку строкой и ждёт, пока документ соберётся. */
export function load(call: Call, html: string): Promise<void>;

/** Спрашивает документ выражением. Исключение внутри страницы поднимается сюда. */
export function ask(call: Call, expression: string): Promise<any>;

/** Какой режим настроен у человека: замер без этого идёт под умолчанием движка. */
export function system(call: Call, half: "light" | "dark"): Promise<unknown>;

/** Снимает кадр в файл. Нужен там, где вопрос про ВИД, а не про вычисленное значение. */
export function shoot(call: Call, path: string): Promise<string>;
